import { SOGNodeType, SOGEdgeType } from '../../sog/sog-core-schema';
/**
 * entity-registry.ts — L1 确定性实体解析 (ARCH-20 Phase A3)
 * 8条零假阳性规则, 直接写入本体图.
 */
import type { GraphStore } from './graph-store';
import type { NodeType } from './types';

export function resolvePersonByEmail(graph: GraphStore, email: string, orgGraph: string): string | null {
  if (!email) return null;
  const existing = graph.queryNodes(SOGNodeType.PERSON, { email: email.toLowerCase() }, orgGraph);
  return existing.length > 0 ? existing[0].id : null;
}

export function resolveToolByUrl(graph: GraphStore, url: string, orgGraph: string): string | null {
  if (!url) return null;
  const existing = graph.queryNodes(SOGNodeType.TOOL, { url }, orgGraph);
  return existing.length > 0 ? existing[0].id : null;
}

export function resolveClientByNameAndIndustry(graph: GraphStore, name: string, industry: string, orgGraph: string): { id: string; confidence: number } | null {
  if (!name || !industry) return null;
  const existing = graph.queryNodes(SOGNodeType.CLIENT, { name, industry }, orgGraph);
  if (existing.length > 0) return { id: existing[0].id, confidence: 1.0 };
  // 3b: name only, confidence 0.95
  const nameOnly = graph.queryNodes(SOGNodeType.CLIENT, { name }, orgGraph);
  if (nameOnly.length === 1) return { id: nameOnly[0].id, confidence: 0.95 };
  return null;
}

