export function resolveOrgByRegistration(graph: GraphStore, name: string, regNumber: string, orgGraph: string): { id: string; confidence: number } | null {
  if (!name) return null;
  // 8a: has registration number
  if (regNumber) {
    const existing = graph.queryNodes(SOGNodeType.TEAM, { name, registrationNumber: regNumber }, orgGraph);
    if (existing.length > 0) return { id: existing[0].id, confidence: 1.0 };
  }
  // 8b: name + domain + industry
  const byName = graph.queryNodes(SOGNodeType.TEAM, { name }, orgGraph);
  if (byName.length === 1) return { id: byName[0].id, confidence: 0.95 };
  return null;
}

/** 合并两个节点: 将 source 的所有边重定向到 target, 然后删除 source */
export function mergePersonNodes(graph: GraphStore, sourceId: string, targetId: string, orgGraph: string): void {
  const edges = graph.queryEdges(undefined, sourceId, undefined, orgGraph);
  for (const e of edges) {
    graph.createEdge(e.type, targetId, e.to, e.weight, e.props, orgGraph);
  }
  const incoming = graph.queryEdges(undefined, undefined, sourceId, orgGraph);
  for (const e of incoming) {
    graph.createEdge(e.type, e.from, targetId, e.weight, e.props, orgGraph);
  }
  graph.deleteNode(sourceId, orgGraph);
}
